#![allow(clippy::unwrap_used)]

use gmm_migoto::{SectionKind, parse};
use proptest::prelude::*;

/// Synthetic, but shaped like real ZZMI/WWMI mod inis.
const MOD: &str = r"
; Generated by a mod tool
namespace = Test\Outfit

[Constants]
global $active = 0

[KeyToggleHat]
condition = $active == 1
key = no_ctrl VK_F6
key = 6
back = VK_F7
type = cycle
$hat = 0,1

[TextureOverrideBodyBlend]
hash = 0FC8027F
handling = skip
if DRAW_TYPE == 2
	vb1 = ResourceBodyTexcoord
endif

[TextureOverrideBodyA]
hash = 9040e2c4
match_first_index = 0
ib = ResourceBodyAIB
ps-t3 = ResourceBodyADiffuse

[TextureOverrideBodyB]
hash = 9040e2c4
match_first_index = 31242
ps-t3 = ResourceBodyBDiffuse

[TextureOverrideWatcher]
hash = 1234abcd
$active = 1

[TextureOverrideNoHash]
ib = ResourceX

[ShaderOverrideGlow]
hash = 00aa11bb22cc33dd
ps-t20 = ResourceGlow

[ResourceBodyAIB]
type = Buffer
filename = BodyA.ib
";

#[test]
fn reads_what_gmm_needs() {
    let ini = parse(MOD);
    assert_eq!(ini.namespace.as_deref(), Some(r"Test\Outfit"));
    assert_eq!(ini.sections, 9);

    let hashes: Vec<(&str, Option<u64>)> = ini
        .overrides
        .iter()
        .map(|o| (o.hash.as_str(), o.first_index))
        .collect();
    assert_eq!(
        hashes,
        [
            ("0fc8027f", None),
            ("9040e2c4", Some(0)),
            ("9040e2c4", Some(31242)),
            ("1234abcd", None),
            ("00aa11bb22cc33dd", None),
        ],
        "lowercased; sections without a hash are dropped"
    );
    let blend = &ini.overrides[0];
    assert!(blend.replaces.geometry && !blend.replaces.textures);
    let a = &ini.overrides[1];
    assert!(a.replaces.geometry && a.replaces.textures);
    let b = &ini.overrides[2];
    assert!(!b.replaces.geometry && b.replaces.textures);
    assert!(
        !ini.overrides[3].replaces.any(),
        "a watcher replaces nothing"
    );
    assert_eq!(ini.overrides[4].kind, SectionKind::ShaderOverride);

    assert!(!a.overlaps(b), "different parts of the same buffer");
    assert!(blend.overlaps(&blend.clone()));

    assert_eq!(ini.keys.len(), 1);
    let key = &ini.keys[0];
    assert_eq!(key.section, "KeyToggleHat");
    assert_eq!(key.keys, ["no_ctrl VK_F6", "6"]);
    assert_eq!(key.back, ["VK_F7"]);
    assert_eq!(key.kind.as_deref(), Some("cycle"));
}

#[test]
fn tolerates_junk() {
    let ini = parse(
        "\u{feff}[TextureOverrideX\nhash = 1\n[TextureOverrideY]\nhash\n= \nhash = \nvb0 = R\n[\n]",
    );
    assert!(ini.overrides.is_empty());
    let ini = parse("[textureoverridelower]\nHASH = AbCd\nIB = x\n");
    assert_eq!(ini.overrides[0].hash, "abcd");
    assert!(ini.overrides[0].replaces.geometry);
}

proptest! {
    #[test]
    fn never_panics(s in ".{0,400}") {
        let _ = parse(&s);
    }

    #[test]
    fn never_panics_on_ini_like_text(lines in proptest::collection::vec(
        prop_oneof![
            "\\[[A-Za-z]{0,20}\\]",
            "[a-z_-]{0,10} = [ -~]{0,20}",
            "if .{0,10}",
            ";.{0,10}",
        ],
        0..40,
    )) {
        let _ = parse(&lines.join("\n"));
    }
}
